actions.script:
for (const recipient of Array.from(financeResult.recipientResults || [])) {
    ec.message.addMessage((recipient.recipient || recipient.toAddress || 'Recipient') + ': ' +
        (recipient.errorMessage || recipient.message || recipient.status || 'Processed'), recipient.errorMessage || recipient.status === 'Failed' ? 'warning' : 'success')
}
